namespace Inventory;

/// <summary>
/// Provides the inventory API while delegating each responsibility to a cohesive service.
/// </summary>
public sealed class StockController
{
    private readonly StockOperations _operations;

    public StockController(ISupplier supplier) => _operations = new StockOperations(supplier);

    public int AdjustStock(StockItem item, int delta) => _operations.AdjustStock(item, delta);

    public int Available(StockItem item) => _operations.Available(item);

    public int MovementCount => _operations.MovementCount;

    public bool NeedsReorder(StockItem item) => _operations.NeedsReorder(item);

    public int ReorderQuantity(StockItem item) => _operations.ReorderQuantity(item);

    public int ResolveThreshold(string sku) => _operations.ResolveThreshold(sku);

    public string AllocateToZone(StockItem item, Warehouse warehouse) =>
        _operations.AllocateToZone(item, warehouse);

    public int ZoneSpare(Warehouse warehouse) => _operations.ZoneSpare(warehouse);

    public bool PlaceReorder(StockItem item) => _operations.PlaceReorder(item);

    public bool ConfirmDelivery(StockItem item, int delivered) =>
        _operations.ConfirmDelivery(item, delivered);

    public string Classify(StockItem item) => _operations.Classify(item);

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse) =>
        _operations.AuditStock(item, warehouse);

    public int ForecastDepletion(StockItem item, int dailyDemand) =>
        _operations.ForecastDepletion(item, dailyDemand);
}

internal sealed class StockOperations
{
    private readonly StockAdjustmentService _adjustments = new();
    private readonly ReorderPolicy _reorder = new();
    private readonly ZoneAllocationService _zones = new();
    private readonly SupplierOrderService _orders;
    private readonly StockAuditService _audit;

    public StockOperations(ISupplier supplier)
    {
        _orders = new SupplierOrderService(supplier, _reorder);
        _audit = new StockAuditService(_zones);
    }

    public int AdjustStock(StockItem item, int delta) => _adjustments.AdjustStock(item, delta);

    public int Available(StockItem item) => _adjustments.Available(item);

    public int MovementCount => _adjustments.MovementCount;

    public bool NeedsReorder(StockItem item) => _reorder.NeedsReorder(item);

    public int ReorderQuantity(StockItem item) => _reorder.ReorderQuantity(item);

    public int ResolveThreshold(string sku) => _reorder.ResolveThreshold(sku);

    public string AllocateToZone(StockItem item, Warehouse warehouse) =>
        _zones.Allocate(item, warehouse);

    public int ZoneSpare(Warehouse warehouse) => _zones.GetSpareCapacity(warehouse);

    public bool PlaceReorder(StockItem item) => _orders.PlaceReorder(item);

    public bool ConfirmDelivery(StockItem item, int delivered) =>
        _orders.ConfirmDelivery(item, delivered);

    public string Classify(StockItem item) => _reorder.Classify(item);

    public IReadOnlyList<string> AuditStock(StockItem item, Warehouse warehouse) =>
        _audit.Audit(item, warehouse);

    public int ForecastDepletion(StockItem item, int dailyDemand) =>
        _reorder.ForecastDepletion(item, dailyDemand);
}

internal sealed class StockAdjustmentService
{
    private readonly List<string> _movements = new();

    public int MovementCount => _movements.Count;

    public int AdjustStock(StockItem item, int delta)
    {
        if (delta == 0)
            return item.OnHand;
        if (delta < 0 && item.OnHand + delta < 0)
            return item.OnHand;

        item.OnHand += delta;
        _movements.Add(delta > 0
            ? $"IN {item.Sku} {delta}"
            : $"OUT {item.Sku} {-delta}");

        if (item.OnHand < item.Reserved)
            _movements.Add($"WARN {item.Sku} oversold");

        return item.OnHand;
    }

    public int Available(StockItem item) => Math.Max(0, item.OnHand - item.Reserved);
}

internal sealed class ReorderPolicy
{
    private const int DefaultReorder = 20;
    private readonly Dictionary<string, int> _thresholds = new(StringComparer.Ordinal);

    public bool NeedsReorder(StockItem item)
    {
        if (item.Sku.Length == 0)
            return false;

        int available = item.OnHand - item.Reserved;
        int threshold = item.ReorderPoint > 0
            ? item.ReorderPoint
            : ResolveThreshold(item.Sku);
        return available <= threshold;
    }

    public int ReorderQuantity(StockItem item)
    {
        if (!NeedsReorder(item))
            return 0;

        int available = item.OnHand - item.Reserved;
        int target = item.ReorderPoint > 0
            ? item.ReorderPoint * 2
            : DefaultReorder * 2;
        int quantity = target - available;

        if (quantity < 0)
            return 0;
        return quantity < 5 ? 5 : quantity;
    }

    public int ResolveThreshold(string sku)
    {
        if (string.IsNullOrEmpty(sku))
            return DefaultReorder;
        return _thresholds.TryGetValue(sku, out int threshold)
            ? threshold
            : DefaultReorder;
    }

    public string Classify(StockItem item)
    {
        int available = item.OnHand - item.Reserved;
        if (available < 0)
            return "oversold";
        if (available == 0)
            return "out";
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return "low";
        if (available > item.ReorderPoint * 5)
            return "excess";
        return "ok";
    }

    public int ForecastDepletion(StockItem item, int dailyDemand)
    {
        if (dailyDemand <= 0)
            return -1;

        int available = item.OnHand - item.Reserved;
        if (available <= 0)
            return 0;

        int days = available / dailyDemand;
        if (item.ReorderPoint > 0 && available <= item.ReorderPoint)
            return 0;
        if (days > 365)
            return 365;
        if (ResolveThreshold(item.Sku) > 0 && available <= ResolveThreshold(item.Sku))
            return 1;
        return days;
    }
}

internal sealed class ZoneAllocationService
{
    private readonly Dictionary<string, int> _usage = new(StringComparer.Ordinal);

    public string Allocate(StockItem item, Warehouse warehouse)
    {
        if (warehouse.Zones.Count == 0)
            return "no zones";

        int need = item.OnHand - item.Reserved;
        if (need <= 0)
            return "nothing to place";

        foreach (var zone in warehouse.Zones)
        {
            int used = GetUsage(zone.Name);
            int spare = zone.Capacity - used;
            if (spare <= 0)
                continue;

            int placed = Math.Min(need, spare);
            _usage[zone.Name] = used + placed;
            need -= placed;
            if (need <= 0)
                return $"placed in {zone.Name}";
        }

        return "overflow";
    }

    public int GetSpareCapacity(Warehouse warehouse)
    {
        int spare = 0;
        foreach (var zone in warehouse.Zones)
        {
            int used = GetUsage(zone.Name);
            if (zone.Capacity > used)
                spare += zone.Capacity - used;
        }
        return spare;
    }

    public int GetUsage(string zoneName) =>
        _usage.TryGetValue(zoneName, out int used) ? used : 0;
}

internal sealed class SupplierOrderService
{
    private readonly ISupplier _supplier;
    private readonly ReorderPolicy _reorder;
    private readonly Dictionary<string, int> _pending = new(StringComparer.Ordinal);

    public SupplierOrderService(ISupplier supplier, ReorderPolicy reorder)
    {
        _supplier = supplier;
        _reorder = reorder;
    }

    public bool PlaceReorder(StockItem item)
    {
        int quantity = _reorder.ReorderQuantity(item);
        if (quantity <= 0)
            return false;
        if (_pending.TryGetValue(item.Sku, out int existing) && existing >= quantity)
            return false;

        bool accepted = _supplier.PlaceOrder(item.Sku, quantity);
        if (accepted)
            _pending[item.Sku] = quantity;
        return accepted;
    }

    public bool ConfirmDelivery(StockItem item, int delivered)
    {
        if (delivered <= 0 || !_pending.TryGetValue(item.Sku, out int pending))
            return false;

        item.OnHand += delivered;
        if (delivered >= pending)
            _pending.Remove(item.Sku);
        else
            _pending[item.Sku] = pending - delivered;
        return true;
    }
}

internal sealed class StockAuditService
{
    private readonly ZoneAllocationService _zones;

    public StockAuditService(ZoneAllocationService zones) => _zones = zones;

    public IReadOnlyList<string> Audit(StockItem item, Warehouse warehouse)
    {
        var findings = new List<string>();
        AddItemFindings(item, findings);
        AddZoneFindings(warehouse, findings);

        if (findings.Count == 0)
            findings.Add("clean");
        return findings;
    }

    private static void AddItemFindings(StockItem item, List<string> findings)
    {
        if (item.OnHand < 0)
            findings.Add($"{item.Sku}:negative-onhand");
        if (item.Reserved < 0)
            findings.Add($"{item.Sku}:negative-reserve");
        if (item.OnHand < item.Reserved)
            findings.Add($"{item.Sku}:oversold");
    }

    private void AddZoneFindings(Warehouse warehouse, List<string> findings)
    {
        foreach (var zone in warehouse.Zones)
        {
            int used = _zones.GetUsage(zone.Name);
            if (used > zone.Capacity)
                findings.Add($"{zone.Name}:over-capacity");
            else if (used < 0)
                findings.Add($"{zone.Name}:negative-usage");
        }
    }
}
